pages=[]
def ids(g,*nums):return [f'UC-{g}-{n:02d}' for n in nums]
def field(k,v):return '<label class="field"><span>'+E(k)+'</span><div class="field-value">'+E(v)+'</div></label>'
def table(head,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+E(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def badge(t,kind=''):return '<span class="badge '+kind+'">'+E(t)+'</span>'
def note(t):return '<p class="note">'+E(t)+'</p>'
def button(t,role='',disabled=False):return '<button type="button" class="action" data-action data-roles="'+role+'"'+(' disabled' if disabled else '')+'>'+E(t)+'</button>'
def link(t,p,tab=''):return '<a class="action secondary" href="#'+p+'"'+(' data-tab-target="'+tab+'"' if tab else '')+'>'+E(t)+'</a>'
def modalbutton(t,id,role):return '<button class="action" type="button" data-open="'+id+'" data-roles="'+role+'">'+E(t)+'</button>'
def actions(*xs):return '<div class="actions">'+''.join(xs)+'</div>'
def tabs(pid,items):
    return '<div class="tabs" role="tablist" aria-label="ส่วนงาน">'+''.join(f'<button role="tab" id="{pid}-tab-{k}" aria-controls="{pid}-panel-{k}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-tab="{k}" data-page="{pid}">{t}</button>' for i,(k,t,b) in enumerate(items))+'</div>'+''.join(f'<div class="tab-panel" role="tabpanel" id="{pid}-panel-{k}" aria-labelledby="{pid}-tab-{k}" {"hidden" if i else ""}>{b}</div>' for i,(k,t,b) in enumerate(items))
def add(id,name,group,ucs,access,body,rule,pending='',extra=''):
    pages.append(dict(id=id,name=name,group=group,ucs=ucs,access=access,body=body,rule=rule,pending=pending,extra=extra))

