def head(title,other):return '<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' · E-Filing</title><link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Thai:wght@400;500;600;700&display=swap" rel="stylesheet"><style>'+css+'</style></head><body><header><div class="eyebrow">E-FILING / TWO-WEEK DELIVERY DESIGN</div><h1>'+title+'</h1><p>ทะเบียนและไฟล์เอกสาร → DAR จนปิด → หลักฐานและการตรวจ → CAR จนปิด ตามบทบาทและสิทธิ์</p><div class="metrics"><span><b>10</b>หน้าหลัก</span><span><b>3</b>ป๊อปอัป</span><span><b>24/28</b>UC ในแบบ</span><span><b>14</b>คนเดโม</span></div><nav class="top-links"><a href="'+other[0]+'">'+other[1]+'</a><a href="MVP_2_Weeks_and_Role_Matrix.md">ขอบเขตและ Role Matrix</a><a href="E-Filing%20ISO%20(MVP%20Mockup).html">เปิด Mockup ล่าสุด</a><a href="../SRS_v1.md">SRS_v1.md</a><a href="#scope">งานที่พัก / จุดรอยืนยัน</a></nav></header><main class="wrap">'
def scope():return '<section class="scope" id="scope"><h2>ขอบเขตรอบนี้</h2><p><strong>23 UC เป้าหมาย + UC-A-11 รวมในหน้า DAR = 24 UC ในแบบ</strong> ไม่ได้หมายถึงผ่านทุกข้อกำหนด เส้นทาง QM/QP/WI/SD/FM ตามมติ Step 3 ใช้ตาราง §6.2; mockup เก่ายังมีข้อจำกัดต่างจากระบบจริง; นำเข้าเอกสารเดิมรักษารหัสเดิมตามประเภท</p><p>เก็บการปิด DAR และวงจร CAR ครบ เกินกำหนดเป็นค่าคำนวณที่แสดงคู่สถานะจริง บัญชีเดโมเลือกบทบาทแล้วเปลี่ยนคนและข้อมูลเข้าสู่ระบบ</p><details><summary>4 Use Case ที่พักเต็ม และ Requirement ที่ยังต้องเก็บ</summary>'+table(['UC','พักอะไร','Requirement ที่พัก','ยังต้องทำ'],[[E(c) for c in row] for row in deferred])+'<p class="fine">UC-A-11 ไม่พักความสามารถ: FR-A-05/15/17/18/19 และ AC-A-13 ยังคงใช้ในแท็บติดตาม DAR; งานความปลอดภัยและการบันทึกเหตุการณ์ไม่ถูกตัด</p></details><details><summary>ข้อกำหนดที่ลดขอบเขต / รอยืนยัน</summary><p>UC-A-02 รองรับสร้างใหม่/แก้ไข QM/QP/WI/SD/FM พร้อมแยกผู้ทบทวนและผู้อนุมัติ ไม่ครอบคลุม DAR ทุกประเภท; UC-B-15 เริ่มค่าสรุปพื้นฐาน ไม่ครอบคลุม FR-B-39.2–39.5 เต็ม ข้อ Must ที่ยังทำไม่ครบต้องระบุเป็นรายการค้างรอบส่งมอบ</p><p>ต้องยืนยันอำนาจมอบหมายรับทราบ จำนวนผู้ลงนามปิด CAR และอำนาจ Lead Auditor/QMR ก่อนผูกสิทธิ์จริง โดยแสดงจุดค้างไว้ในหน้าที่เกี่ยวข้อง</p></details></section>'

def role_matrix():
    rows=[]
    actions_by_role={'dcc':'นำเข้า / จัดทำ QM / ตรวจรับ / ประกาศใช้; ไม่อนุมัติเอง','owner':'ยื่น DAR / ติดตามของตน','reviewer':'ทบทวน QP/WI; FM ยังรอยืนยัน','qmr':'ทบทวน QM / อนุมัติ QP/WI / มอบหมายผู้ช่วยเป็นรายงาน','deputy':'เฉพาะรายการที่ได้รับมอบหมาย บันทึกชื่อผู้ช่วยเอง','dean':'อนุมัติ QM หลังผ่านทบทวน ไม่ใช่ Sponsor','sponsor':'สรุปรวมอย่างเดียว ห้ามเจาะรายบุคคล','lead':'สร้างรอบตรวจ / มอบหมายผู้ตรวจ; อนุมัติแผนและปิดยังรอยืนยัน','assistant':'ตรวจประสิทธิผลเฉพาะใบที่ได้รับมอบหมาย ห้ามปิด','sectionhead':'ความเห็นร่วมรับรองแผนกลุ่มงาน ไม่เปลี่ยนผลอนุมัติ','carowner':'แก้ไขและแนบผลเฉพาะใบตน ห้ามตรวจ/ปิด','auditor':'Finding / เปิดใบ / ตรวจประสิทธิผลตามงาน','registrar':'ตรวจรับ / แจกจ่าย / เรียกคืน / ปิด DAR','reader':'อ่านและรับทราบฉบับที่ได้รับมอบหมาย'}
    for k,t,n,e in roles:
        visible=[name for key,icon,name,allowed in MOCK_NAV if k in allowed]
        rows.append([E(t),E(' · '.join(visible)),E(actions_by_role[k])])
    return '<section class="matrix" id="matrix"><h2>14 บทบาท · เมนูและอำนาจตาม mockup</h2><p>การมองเห็นเมนูไม่ใช่สิทธิ์ทำทุกรายการ ข้อมูลยังกรองตามผู้รับผิดชอบ การมอบหมาย และกลุ่มงาน</p>'+table(['บทบาท','เมนู','ขอบเขตการกระทำ'],rows)+'</section>'

def dialogs():
    m1='<div class="two"><label>โหมด<select id="document-mode"><option value="import">นำเข้าเอกสารเดิม — เก็บรหัสเดิม</option></select></label><label>ประเภท<select id="document-type">'+''.join('<option>'+x+'</option>' for x in ['QM','QP','WI','SD','FM'])+'</select></label></div><label>รหัสจากต้นฉบับ<input id="document-code" value="QM-2301-01"></label><p id="code-hint" class="fine">นำเข้าเดิมตรวจรหัสจากต้นฉบับ ไม่ออกรหัสทับ</p>'+field('ชื่อ / ส่วนงาน / ผู้รับผิดชอบ','ข้อมูลที่ต้องกรอกจากเอกสาร')+field('Rev / วันที่มีผล / สถานะ','นำเข้าจากหลักฐานเดิม ไม่ใช้วันอัปโหลดแทนวันมีผล')+'<label>ไฟล์ PDF<input type="file" accept="application/pdf,.pdf" data-file></label><p data-file-info class="fine">ยังไม่ได้เลือกไฟล์</p>'+note('แสดงวิธีนำไฟล์เข้าในแบบหน้าจอเท่านั้น เลือกไฟล์ได้แต่ไม่อัปโหลด/บันทึก server ใน Atlas')+button('บันทึกรายการและไฟล์ — ตัวอย่าง')
    m2=field('ชนิด / ชื่อ / วันที่ / รายละเอียด','บันทึกการอบรมหรือหลักฐานประกอบ')+field('ผูกกับรายการ','Record / Finding / CAR ตามกรณี; ไม่บังคับสร้าง Record ก่อน')+'<label>เลือกไฟล์หลักฐาน<input type="file" accept="application/pdf,.pdf" data-file></label><p data-file-info class="fine">ยังไม่ได้เลือกไฟล์</p>'+button('บันทึกพร้อมหลักฐาน — ตัวอย่าง')
    m3=field('รอบตรวจหรือแหล่งที่มา','ตรวจติดตามภายใน / ประชุมทบทวนฝ่ายบริหาร')+field('ชนิดประเด็น','ความไม่สอดคล้อง / ข้อสังเกต / ข้อเสนอแนะ')+field('ข้อกำหนด / ข้อเท็จจริง / ระดับความรุนแรง','กรอกและอ้างหลักฐาน ไม่ให้ระบบเลือกความรุนแรงแทน')+'<label>หลักฐาน<input type="file" accept="application/pdf,.pdf" data-file></label><p data-file-info class="fine">ยังไม่ได้เลือกไฟล์</p>'+button('บันทึก Finding — ตัวอย่าง')
    return ''.join('<dialog id="'+id+'" aria-labelledby="'+id+'-title"><div class="dialog-head"><h2 id="'+id+'-title">'+title+'</h2><button class="close-dialog" type="button" data-close aria-label="ปิดหน้าต่าง">×</button></div>'+body+'</dialog>' for id,title,body in [('M01','เพิ่ม / นำเข้าเอกสาร',m1),('M02','เพิ่มบันทึกและหลักฐาน',m2),('M03','เพิ่มประเด็นที่พบ',m3)])

nav=''.join('<a href="#'+p['id']+'" data-nav="'+p['id']+'">'+p['id']+' '+p['name']+'</a>' for p in pages)
atlas=head('Screen Atlas · ขอบเขต 2 สัปดาห์',('Screen%20Flow.html','เปิด Screen Flow'))+scope()
atlas+='<section class="controls"><div class="controls-row"><label for="role-preview">ดูเมนูและปุ่มของ</label><select id="role-preview"><option value="all">ทุกบทบาท — ภาพรวมสำหรับทบทวน</option>'+''.join('<option value="'+k+'">'+E(n+' · '+t)+'</option>' for k,t,n,e in roles)+'</select><span class="account" id="account">เลือกคนเพื่อดูขอบเขตที่ออกแบบไว้</span></div><nav class="page-nav" aria-label="หน้าจอหลัก">'+nav+'</nav><p class="fine">ตัวเลือกนี้ช่วยทบทวนเมนู ปุ่ม และเงื่อนไข; ข้อมูลตัวอย่างในตารางเป็นชุดคงที่ ไม่ใช่การทดสอบกรองข้อมูลหรือสิทธิ์จริง</p></section>'
for p in pages:
    uc=''.join('<div><span class="pill-uc">'+u+'</span> §'+source[u]['section']+' '+E(source[u]['title'])+'</div>' for u in p['ucs'])
