# Static SVG diagrams remain complete without JavaScript. Each node links into Atlas.
def svg_open(slug,title,desc,w,h):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-labelledby="{slug}-title {slug}-desc"><title id="{slug}-title">{E(title)}</title><desc id="{slug}-desc">{E(desc)}</desc><defs><marker id="{slug}-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z" fill="#62758d"/></marker></defs>'
def edge(slug,path,dashed=False):return '<path d="'+path+'" fill="none" stroke="#62758d" stroke-width="2"'+(' stroke-dasharray="6 5"' if dashed else '')+' marker-end="url(#'+slug+'-arrow)"/>'
def node(x,y,w,h,title,sub,p,tab='',focus=False):
    href='Screen%20Atlas.html'+('?tab='+tab if tab else '')+'#'+p
    return f'<a href="{href}" aria-label="เปิด {E(title)} ใน Screen Atlas"><rect x="{x}" y="{y}" width="{w}" height="{h}" rx="6" fill="{ "#eaf4ee" if focus else "#ffffff"}" stroke="{ "#14664c" if focus else "#899eb8"}" stroke-width="1.6"/><text x="{x+16}" y="{y+30}" font-size="19" font-weight="600">{E(title)}</text><text x="{x+16}" y="{y+58}" font-size="15">{E(sub)}</text><text x="{x+16}" y="{y+h-14}" font-size="12" fill="#506176">{p} · คลิกดูหน้าจอ</text></a>'
def flowcard(id,title,desc,svg,notes):return '<section class="flow-card" id="'+id+'"><h2>'+title+'</h2><p>'+desc+'</p><div class="diagram-scroll">'+svg+'</div><div class="legend"><span>กล่อง = หน้าจอหรือส่วนงานในหน้าจอ</span><span>ลูกศรทึบ = ทางหลัก</span><span>เส้นประ = ส่งกลับพร้อมเหตุผล</span></div>'+notes+'</section>'

